/* Ink sprite sheets (6 frames x 256px, white on transparent) — artwork by the Ink Squadron team */
var SPRITES = { ready: false, img: {}, tint: {}, src: {
  scribble: 'data:image/png;base64,',
  splat1: 'data:image/png;base64,',
  splat2: 'data:image/png;base64,',
  splat3: 'data:image/png;base64,',
} };
(function () {
  let left = 0;
  for (const k in SPRITES.src) { left++; const im = new Image(); im.onload = () => { if (--left === 0) SPRITES.ready = true; }; im.src = SPRITES.src[k]; SPRITES.img[k] = im; }
})();
function spriteTint(name, color) {
  const key = name + '|' + color; let c = SPRITES.tint[key]; if (c) return c;
  const im = SPRITES.img[name]; c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
  const g = c.getContext('2d'); g.drawImage(im, 0, 0); g.globalCompositeOperation = 'source-in'; g.fillStyle = color; g.fillRect(0, 0, c.width, c.height);
  SPRITES.tint[key] = c; return c;
}
/* draw frame f (0..5) of a sheet centred at x,y with size s (px), tinted */
function drawSprite(name, f, x, y, s, color, alpha, rot, flip) {
  if (!SPRITES.ready || !SPRITES.img[name]) return;
  const c = spriteTint(name, color || NAVY), fw = c.height;
  ctx.save(); ctx.translate(x, y); if (rot) ctx.rotate(rot); if (flip) ctx.scale(-1, 1);
  if (alpha != null) ctx.globalAlpha *= alpha;
  ctx.drawImage(c, (f | 0) * fw, 0, fw, fw, -s / 2, -s / 2, s, s); ctx.restore();
}
